import{_ as o,c as t,o as n,ah as r}from"./chunks/framework.PvdZnrZd.js";const h=JSON.parse('{"title":"Postcode Shipping","description":"Postcode Shipping","frontmatter":{"title":"Postcode Shipping","description":"Postcode Shipping","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/marketplace-shipping/postcode-shipping.md","filePath":"zenith/marketplace-shipping/postcode-shipping.md"}'),p={name:"zenith/marketplace-shipping/postcode-shipping.md"};function a(s,e,l,i,g,d){return n(),t("div",null,[...e[0]||(e[0]=[r(`<p><strong>Postcode Shipping</strong>: You can provide your customers shipping rates based on postcode ranges by enabling the free <a href="https://webkul.com/blog/shopify-multivendor-marketplace-shipping/" target="_blank" rel="noreferrer"><strong>Shipping Add-on</strong></a> within the <strong>Multivendor Marketplace App</strong> for <strong>Shopify</strong>.</p><p><strong>Before You Install</strong>: It is mandatory to have <strong><a href="https://help.shopify.com/en/manual/shipping/setting-up-and-managing-your-shipping/enabling-shipping-carriers" target="_blank" rel="noreferrer">real-time carrier calculated shipping</a></strong> within your Shopify store. This is a requirement defined by Shopify for your store to retrieve shipping rates from third-party sources, such as this shipping app.</p><p><strong>Enable the Add-on</strong>: Visit Multivendor Admin Panel &gt; <strong>Feature Apps</strong> &gt; Enable the Add-on. This add-on has three different methods to provide shipping rates: <strong>Country-wise</strong>, <strong>Zone-wise</strong> &amp; <strong>Postcode-wise</strong>. These can be added on the basis on <strong>Price</strong> or <strong>Weight</strong> of the product.</p><p>In this documentation, we&#39;ll learn how to setup Postcode-wise Shipping. In case you want to know more about the rest two (country &amp; zone-wise), kindly <a href="https://webkul.com/blog/shopify-multivendor-marketplace-shipping/" target="_blank" rel="noreferrer">click here</a>.</p><p><strong>Note</strong>: At least one zone must be created at Shopify end. Learn how to do it <a href="https://help.shopify.com/en/manual/shipping/setting-up-and-managing-your-shipping/setting-up-shipping-zones" target="_blank" rel="noreferrer">here</a>.</p><p>Check the below video of Postcode Shipping:</p><p>MUlX7m6ePj0</p><p>Once you&#39;ll install the add-on, visit Multivendor Admin Panel &gt; Configuration &gt; Shipping Methods. <strong>Edit</strong> the <strong>Marketplace Shiping</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode1.webp" alt="image-37"></a></p><p>On the redirected page, configure the required information. Select postcode-wise as shipping type:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode2.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode2.webp" alt="image-39"></a></p><p>When you are choosing postcode wise shipping, it is mandatory to add postal code length. Moreover, there are label translation options here.</p><p><strong>Note</strong>: Postcode Wise Shipping method is not compatible with other Shipping Methods provided in the marketplace. So, if you want to use this method, kindly disable all the other shipping methods.</p><p>You can enable the country in postcode if you want. <strong>Note</strong>: If you want to enable or disable this option then you will loose all your previous postcode zone configurations. Also, it is not compatible with store pickup functionality.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode3.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode3.webp" alt="image-40"></a></p><h2 id="add-shipping-method" tabindex="-1">Add Shipping Method <a class="header-anchor" href="#add-shipping-method" aria-label="Permalink to &quot;Add Shipping Method&quot;">​</a></h2><p>Next, you need to add shipping method by visiting <strong>Configuration</strong> &gt; <strong>Shipping Methods</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode4.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode4.webp" alt="image-35"></a></p><p>Add the name and save:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode5.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode5.webp" alt="image-141"></a></p><p>Upon saving, they will be listed under shipping configuration page. From here, they can be edited/enabled/disabled.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode6-1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode6-1.webp" alt="image-142"></a></p><p>Now, once you&#39;ll add the postcode shipping, you&#39;ll get an option to configure postcode. On the shipping configuration page:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/Configuration-Admin-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/Configuration-Admin-1200x597.png" alt="Configuration-Admin"></a></p><p>Or, visit <strong>Configuration</strong> &gt; <strong>Postcode Zone</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode8.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode8.webp" alt="image-36"></a></p><p>On the <strong>Postcode Zone Details</strong> page, click on <strong>Add Postcode Zone</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode9.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode9.webp" alt="image-136"></a></p><p>Here, you need to enter the postcode zone name, enable the status, and choose the method to add postal code. There are two ways: <strong>Manually</strong> or via <strong>CSV</strong> file.</p><p>For manually, you just need to enter the postal code one by one manually:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode10.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode10.webp" alt="image-137"></a></p><p>Add Manually</p><p>In case of CSV file, add 5000 postcodes at once:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode11.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode11.webp" alt="postal code"></a></p><p>Note: In one postcode zone, you can add a maximum of 100,000 postcodes.</p><p>Once added, they&#39;ll be listed as such:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode12.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/postcode12.webp" alt="image-139"></a></p><p>Clicking on <strong>Edit</strong> will take you back to the edit postcode zone page.</p><p>To add shipping to a postcode zone, click on <strong>Add Shipping</strong>. Here, click on <strong>Choose Shipping Method</strong> &gt; Select the <strong>Shipping Methods</strong> &amp; save.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode21.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode21.webp" alt="image-144"></a></p><p>Once done, they can also be edited or removed:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode22.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode22.webp" alt="image-145"></a></p><p>Clicking on View Postcode will give you add the added postcodes for that particular zone:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode23.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode23.webp" alt="image-146"></a></p><p>Further, these shipping methods can be enabled &amp; disabled for the sellers from the edit seller page:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode24.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode24.webp" alt="image-147"></a></p><h2 id="configure-front-end" tabindex="-1">Configure front-end <a class="header-anchor" href="#configure-front-end" aria-label="Permalink to &quot;Configure front-end&quot;">​</a></h2><p>You need to add a few codes to the template files. The instructions are given under <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Instructions for Marketplace</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode25.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode25.webp" alt="image-148"></a></p><h2 id="seller-panel" tabindex="-1">Seller Panel <a class="header-anchor" href="#seller-panel" aria-label="Permalink to &quot;Seller Panel&quot;">​</a></h2><p>Visit <strong>Multivendor Seller Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Shipping Configuration</strong>.</p><p>Seller will have the list of all the shipping methods added by the admin. From this page, seller can enable/disable the postwise shipping methods.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode26.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode26.webp" alt="image-157"></a></p><p>Under Marketplace Shipping, seller will have three options: Enable/Disable Shipping, Postcode Zones &amp; Range Details.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone27.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone27.webp" alt="image-150"></a></p><h3 id="_1-postcode-zones" tabindex="-1">1. Postcode Zones <a class="header-anchor" href="#_1-postcode-zones" aria-label="Permalink to &quot;1\\. Postcode Zones&quot;">​</a></h3><p>Here, the seller will have the list of all the shipping postcode zones added by admin:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone28.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone28.webp" alt="image-152"></a></p><p><strong>ADD/EDIT PRICE</strong>: Here, you can add shipping charge for different shipping methods for all kind of ranges.</p><p>You can choose the shipping method and add the shipping charges based on the range. In case you don&#39;t want to charge for a particular range, keep that empty.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone29.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone29.webp" alt="image-153"></a></p><p>Seller can also add the shipping charges via CSV file:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode30.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcode30.webp" alt="image-154"></a></p><p>Download the sample CSV file to know the right format. In the CSV you have to add two fields: Range ID &amp; Shipping Courier Name.</p><p>This is the <a href="https://www.qsnapnet.com/snaps/4ikxwhiz8q" target="_blank" rel="noreferrer">Range ID</a> and this is the <a href="https://prnt.sc/tqz12f" target="_blank" rel="noreferrer">Shipping Courier Name</a>.</p><p><strong>VIEW POSTCODE</strong>: Here, seller will have the list of all the postcode added by admin for that particular zone.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-155-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-155-1200x597.png" alt="image-155"></a></p><h3 id="_2-range-details" tabindex="-1">2. Range Details <a class="header-anchor" href="#_2-range-details" aria-label="Permalink to &quot;2\\. Range Details&quot;">​</a></h3><p>Shipping Range is very important for a shipping method. You cannot access a shipping method without any shipping range. So you have to set at least one range for the shipping method. You can set up to eight ranges for a shipping method.</p><p>Ranges can be added based on <strong>price</strong> or either <strong>weight</strong>.</p><p>Here&#39;s an example to understand the lower and upper limits of a defined range:</p><p>Range 1 (1-10lb) - here the upper limit is 10.99lb<br> Range 2 (11-20lb) - here the upper limit is 20.99lb<br> So, product A of weight 10.75lb will be covered under the range 1 (1-10lb)</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone31.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone31.webp" alt="image-158"></a></p><p>Edit/Delete Already Added Shipping Ranges</p><p>You can also add new shipping ranges:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone32.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/postcodezone32.webp" alt="image-159"></a></p><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><p>Customers need to add their postcode and get the details of the shipping rates and methods for that particular zone.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-156.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-156.png" alt="postcode shipping frontend"></a></p><p>To get calculated shipping rates on the cart page, check out this <a href="https://webkul.com/blog/shopify-multivendor-marketplace-shipping-calculator/" target="_blank" rel="noreferrer">blog</a>.</p><p><strong>Note</strong>: If a cart has two products from two different sellers, the shipping will be applied one that is common between both the sellers.</p><h2 id="postcode-shipping-flow-summary" tabindex="-1">Postcode Shipping Flow Summary <a class="header-anchor" href="#postcode-shipping-flow-summary" aria-label="Permalink to &quot;Postcode Shipping Flow Summary&quot;">​</a></h2><p><strong>Lets See How The Postcode Wise Shipping Works</strong></p><h3 id="admin-side-flow" tabindex="-1">Admin Side Flow: <a class="header-anchor" href="#admin-side-flow" aria-label="Permalink to &quot;Admin Side Flow:&quot;">​</a></h3><p><strong>STEPS</strong></p><p><strong>1</strong>: Admin has created a Postcode Zone with the name (ZONE X).<br><strong>2</strong>: Added postal code for this zone (ZONE X).<br><strong>3</strong>: Admin created three postcode shipping:<br> Next Day Delivery<br> Standard Delivery<br> Express Delivery</p><p><strong>Step 4</strong>: Added postcode wise shipping for this postcode (Zone X)<br> Now For Zone X ( Next Day Delivery, Standard Delivery, Express Delivery), all this shipping is applicable.</p><h2 id="seller-side-flow" tabindex="-1">Seller Side Flow: <a class="header-anchor" href="#seller-side-flow" aria-label="Permalink to &quot;Seller Side Flow:&quot;">​</a></h2><h4 id="seller-a" tabindex="-1"><strong>Seller A</strong> <a class="header-anchor" href="#seller-a" aria-label="Permalink to &quot;**Seller A**&quot;">​</a></h4><p><strong>STEPS</strong></p><p><strong>1</strong>: Now Seller can choose any shipping form these (Next Day Delivery, Standard Delivery, Express Delivery).</p><pre><code>     Suppose Seller A Choose (Next Day Delivery , Standard Delivery) 
</code></pre><p><strong>2</strong>: Seller A has created 2 Ranges Bases On Price(Rs)<br> Range I =&gt; 0 - 100<br> Range II =&gt; 101 - 200</p><p><strong>3</strong>: Now Seller Has to Set Price For Ranges For the Shipping Method choose by him (For Zone X)</p><pre><code>     Next Day Delivery

     (Shipping Ranges)                    (Shipping Charge)
        0  - 100                               5
        101 - 200                              10

    Standard Delivery

     (Shipping Ranges)                    (Shipping Charge)
        0  - 100                               2
        101 - 200                              4
</code></pre><h4 id="seller-b" tabindex="-1">Seller B <a class="header-anchor" href="#seller-b" aria-label="Permalink to &quot;Seller B&quot;">​</a></h4><p><strong>Step 1</strong>: Now Seller can choose any shipping form these (Next Day Delivery, Standard Delivery, Express Delivery).</p><pre><code>     Suppose Seller B Choose (Next Day Delivery , Standard Delivery , Express  Delivery) 
</code></pre><p><strong>Step 2</strong>: Seller B has created 2 Ranges Bases On Price(Rs)<br> Range I =&gt; 0 - 100<br> Range II =&gt; 101 - 200</p><p><strong>Step 3</strong>: Now Seller Has to Set Price For Ranges For the Shipping Method choose by him (For Zone X)</p><pre><code>     Next Day Delivery

     (Shipping Ranges)                    (Shipping Charge)
        0  - 100                               3
        101 - 200                              5

    Standard Delivery

     (Shipping Ranges)                    (Shipping Charge)
        0  - 100                               2
        101 - 200                              4

    Express Delivery

     (Shipping Ranges)                    (Shipping Charge)
        0  - 100                               1.5
        101 - 200                              2.5   
</code></pre><p><strong>Store configuration has been completed. Lets&#39;s move on to checkout page.</strong></p><p>Now, the customer has entered his proper address with postal code than we check if the postcode provide by the customer is available in Zone X Or Not if yes then only shipping will be provided at the checkout out page.</p><p><strong>CASES</strong></p><p><strong>I</strong>: If customer choose Product Of Seller A of the price (80)<br> Then at checkout page customer will get</p><pre><code>     Next Day Delivery =&gt; 5 (Shipping Cost)
     Standard Delivery =&gt; 2 (Shipping Cost)
</code></pre><p><strong>II</strong>: If customer choose Product Of Seller A of the price (150)<br> Then at checkout page customer will get</p><pre><code>     Next Day Delivery =&gt; 10 (Shipping Cost)
     Standard Delivery =&gt; 4 (Shipping Cost)
</code></pre><p><strong>III</strong>: If customer choose Product Of Seller B of the price (80)<br> Then at checkout page customer will get</p><pre><code>     Next Day Delivery =&gt; 3 (Shipping Cost)
     Standard Delivery =&gt; 2 (Shipping Cost)
     Express Delivery   =&gt; 1.5 (Shipping Cost)
</code></pre><p><strong>IV</strong>: If customer choose Product Of Seller B of the price (150)<br> Then at checkout page customer will get</p><pre><code>     Next Day Delivery =&gt; 5 (Shipping Cost)
     Standard Delivery =&gt; 4 (Shipping Cost)
     Express Delivery   =&gt; 2.5 (Shipping Cost)
</code></pre><p><strong>V</strong>: If the customer chooses one Product of Seller A of Price (30) and One Product Of Seller B (80)<br> Then at checkout page customer will get</p><pre><code>     Next Day Delivery =&gt; 5 + 3  = 8 (Shipping Cost)
     Standard Delivery =&gt; 2 + 2  = 4 (Shipping Cost)

     Note: If different seller products are added in the cart in that case only those shipping which is common to both the seller are available at the time of checkout.
            If no shipping is common between both sellers than the customer will not be able to checkout out(in that case the customer has to check out each product individually).
</code></pre>`,114)])])}const b=o(p,[["render",a]]);export{h as __pageData,b as default};
